@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap');

:root {
  color-scheme: dark;
}

html, body, #root {
  height: 100%;
  overflow: hidden;
}

body {
  background: #0a0b0d;
  color: #e2e8f0;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 13px;
  line-height: 1.4;
}

.font-mono, .mono {
  font-family: 'JetBrains Mono', 'Fira Code', ui-monospace, monospace;
}

/* Orderbook depth bar animation */
.depth-bar {
  position: absolute;
  top: 0;
  bottom: 0;
  opacity: 0.15;
  transition: width 0.15s ease;
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: #2d3748;
  border-radius: 2px;
}
::-webkit-scrollbar-thumb:hover {
  background: #4a5568;
}

/* Slider custom styles */
input[type='range'] {
  -webkit-appearance: none;
  appearance: none;
  height: 4px;
  border-radius: 2px;
  background: #1e2230;
  outline: none;
}
input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #3b82f6;
  cursor: pointer;
  border: 2px solid #0f1117;
  transition: transform 0.1s;
}
input[type='range']::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

/* Panel border */
.panel {
  border: 1px solid #1e2230;
  background: #13151a;
  border-radius: 4px;
}

.panel-header {
  border-bottom: 1px solid #1e2230;
  padding: 8px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #8892a4;
}

/* Number flash animation */
@keyframes flash-green {
  0% { color: #00d084; }
  100% { color: inherit; }
}
@keyframes flash-red {
  0% { color: #ff4136; }
  100% { color: inherit; }
}

.flash-up {
  animation: flash-green 0.6s ease;
}
.flash-down {
  animation: flash-red 0.6s ease;
}

/* Tab styles */
.tab-btn {
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 500;
  color: #8892a4;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: color 0.15s, border-color 0.15s;
  white-space: nowrap;
}
.tab-btn:hover {
  color: #e2e8f0;
}
.tab-btn.active {
  color: #e2e8f0;
  border-bottom-color: #3b82f6;
}

/* Table styles */
.data-table {
  width: 100%;
  border-collapse: collapse;
}
.data-table th {
  font-size: 11px;
  font-weight: 500;
  color: #4a5568;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 6px 8px;
  text-align: right;
  border-bottom: 1px solid #1e2230;
  white-space: nowrap;
}
.data-table th:first-child {
  text-align: left;
}
.data-table td {
  padding: 7px 8px;
  text-align: right;
  font-size: 12px;
  color: #e2e8f0;
  border-bottom: 1px solid rgba(30,34,48,0.5);
  font-family: 'JetBrains Mono', monospace;
  white-space: nowrap;
}
.data-table td:first-child {
  text-align: left;
  font-family: 'Inter', sans-serif;
}
.data-table tr:last-child td {
  border-bottom: none;
}
.data-table tr:hover td {
  background: rgba(26,29,38,0.6);
}

