  --background: 222 47% 5%;
  --surface: 222 40% 8%;
  --surface-raised: 222 35% 11%;
  --border: 222 25% 18%;
  --text-primary: 210 40% 95%;
  --text-secondary: 215 20% 60%;
  --accent: 252 100% 68%;
  --accent-glow: 252 100% 68%;
  --green: 142 72% 50%;
  --red: 0 72% 58%;
  --yellow: 45 92% 58%;
  --blue: 210 100% 60%;
  --purple: 262 80% 65%;
}

@theme inline {
  --color-bg: hsl(var(--background));
  --color-surface: hsl(var(--surface));
  --color-surface-raised: hsl(var(--surface-raised));
  --color-border: hsl(var(--border));
  --color-text: hsl(var(--text-primary));
  --color-muted: hsl(var(--text-secondary));
  --color-accent: hsl(var(--accent));
  --color-green: hsl(var(--green));
  --color-red: hsl(var(--red));
  --color-yellow: hsl(var(--yellow));
  --color-blue: hsl(var(--blue));
  --color-purple: hsl(var(--purple));
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: hsl(var(--background));
  color: hsl(var(--text-primary));
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  -webkit-font-smoothing: antialiased;
}

::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: hsl(var(--surface));
}
::-webkit-scrollbar-thumb {
  background: hsl(var(--border));
  border-radius: 3px;
}

