@import "tailwindcss";

@theme {
  --color-bg-base: #0a0c10;
  --color-bg-panel: #0f1117;
  --color-bg-surface: #161b24;
  --color-bg-elevated: #1c2333;
  --color-border: #1e2d40;
  --color-border-bright: #2a3f5a;

  --color-accent: #00d4aa;
  --color-accent-dim: #007d65;
  --color-accent-glow: rgba(0, 212, 170, 0.15);

  --color-buy: #00d4aa;
  --color-sell: #f0545c;
  --color-warn: #f5a623;
  --color-info: #4fa3e3;

  --color-text-primary: #e2e8f0;
  --color-text-secondary: #7a8ea8;
  --color-text-dim: #3d5068;

  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', ui-monospace, monospace;
}

:root {
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--color-bg-base);
  color: var(--color-text-primary);
  font-family: var(--font-mono);
  font-size: 13px;
  line-height: 1.6;
  overflow-x: hidden;
}

::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--color-border-bright);
  border-radius: 2px;
}

.scanline {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.03) 2px,
    rgba(0, 0, 0, 0.03) 4px
  );
  z-index: 9999;
}

@keyframes blink {
  0%, 50% { opacity: 1; }
  51%, 100% { opacity: 0; }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 4px var(--color-accent); }
  50% { box-shadow: 0 0 12px var(--color-accent), 0 0 24px var(--color-accent-glow); }
}

@keyframes slide-in {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes spin-slow {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.animate-blink { animation: blink 1s step-end infinite; }
.animate-pulse-glow { animation: pulse-glow 2s ease-in-out infinite; }
.animate-slide-in { animation: slide-in 0.15s ease-out; }
.animate-spin-slow { animation: spin-slow 3s linear infinite; }

.status-executing { color: var(--color-accent); }
.status-idle { color: var(--color-text-secondary); }
.status-stopped { color: var(--color-sell); }
.status-error { color: var(--color-sell); }

.log-info { color: var(--color-info); }
.log-trade-buy { color: var(--color-buy); }
.log-trade-sell { color: var(--color-sell); }
.log-warn { color: var(--color-warn); }
.log-error { color: var(--color-sell); }
.log-system { color: var(--color-text-dim); }

.pnl-positive { color: var(--color-buy); }
.pnl-negative { color: var(--color-sell); }
.pnl-neutral { color: var(--color-text-secondary); }

.panel {
  background: var(--color-bg-panel);
  border: 1px solid var(--color-border);
  border-radius: 4px;
}

.panel-header {
  padding: 8px 12px;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-secondary);
}

.kill-btn {
  background: rgba(240, 84, 92, 0.1);
  border: 1px solid #f0545c;
  color: #f0545c;
  padding: 6px 16px;
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  border-radius: 3px;
  transition: all 0.15s;
}
.kill-btn:hover {
  background: rgba(240, 84, 92, 0.2);
  box-shadow: 0 0 12px rgba(240, 84, 92, 0.3);
}
.kill-btn:active {
  transform: scale(0.97);
}
.kill-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.run-btn {
  background: rgba(0, 212, 170, 0.1);
  border: 1px solid var(--color-accent);
  color: var(--color-accent);
  padding: 6px 16px;
  font-family: var(--font-mono);
